from g import *
S = SETUP_STD
RSS = lambda n: http(n, 'GET', "={{ $('Config').first().json.feedUrl }}")
# 25
A('25', 'blog-to-social', 'Blog post to social repurposer', 'Marketing', 'Give it a blog URL; it fetches the article, writes a LinkedIn post, an X thread and an Instagram caption in your voice and saves drafts to a sheet for review.',
 ('webhook', 'repurpose'), [cfg(brandVoice='clear, practical, no hype'), norm("return [{json:{url:b.url}}];"), http('Fetch article', 'GET', '={{ $json.url }}'),
  code('Extract text', "const html=String($input.first().json.data||$input.first().json.body||JSON.stringify($input.first().json));const text=html.replace(/<script[\\s\\S]*?<\\/script>/gi,' ').replace(/<style[\\s\\S]*?<\\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\\s+/g,' ').trim().slice(0,6000);return [{json:{...$('Normalize').first().json,text}}];"),
  ai('Write posts', 'Repurpose an article into social posts in the given voice. JSON: {"linkedin":"","x_thread":["tweet1","tweet2","tweet3"],"instagram":"","hashtags":["",""]}', "JSON.stringify({voice:$('Config').first().json.brandVoice,article:$json.text})"),
  row('Row: drafts', "return [{json:{date:new Date().toISOString(),url:j.url,linkedin:j.ai.linkedin,x_thread:j.ai.x_thread.join('\\n---\\n'),instagram:j.ai.instagram,hashtags:j.ai.hashtags.join(' '),status:'DRAFT'}}];"), sheet_append('Save drafts')],
 {'url': 'https://example.com/blog/post'}, S, {'Fetch article': {'data': '<html><body><h1>5 tips</h1><p>Tip one is to measure.</p></body></html>'}, 'AI: Write posts': {'linkedin': 'LI post', 'x_thread': ['1', '2', '3'], 'instagram': 'IG caption', 'hashtags': ['#a', '#b']}}, ['Save drafts'])
