A('26', 'video-to-newsletter', 'Video or podcast transcript to newsletter', 'Marketing', 'Post a transcript (from Whisper, Descript or YouTube captions) and get a newsletter draft with subject lines, key takeaways and a call to action by email.',
 ('webhook', 'transcript'), [cfg(), norm("return [{json:{title:b.title||'Untitled',transcript:String(b.transcript||'').slice(0,12000),link:b.link||''}}];"),
  ai('Newsletter', 'Turn a transcript into a newsletter. JSON: {"subjects":["3 options"],"intro":"","takeaways":["5 bullets"],"cta":""}', "JSON.stringify($json)"),
  mail('Email draft', "$('Config').first().json.emailTo", "'Newsletter draft: ' + $json.title", "'SUBJECTS\\n' + $json.ai.subjects.join('\\n') + '\\n\\n' + $json.ai.intro + '\\n\\n' + $json.ai.takeaways.map(t => '- ' + t).join('\\n') + '\\n\\n' + $json.ai.cta + '\\n\\nWatch: ' + $json.link")],
 {'title': 'Episode 12', 'transcript': 'Today we talk about pricing...', 'link': 'https://youtu.be/x'}, S, {'AI: Newsletter': {'subjects': ['A', 'B', 'C'], 'intro': 'Hi', 'takeaways': ['1', '2', '3', '4', '5'], 'cta': 'Reply to me'}}, ['Email draft'])
