A('27', 'rss-weekly-digest', 'Weekly industry digest from RSS', 'Marketing', 'Every Friday pulls your industry RSS feed, keeps the best 10 recent items by keyword match, has AI write a 5-bullet digest and emails it to you or your list.',
 weekly(5, 15), [cfg(feedUrl='https://news.ycombinator.com/rss', keywords='ai,automation,startup'), RSS('Fetch feed'),
  code('Pick items', "const raw=String($input.first().json.data||'');const items=[...raw.matchAll(/<item>([\\s\\S]*?)<\\/item>/g)].map(m=>({title:(m[1].match(/<title>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/title>/)||[])[1]||'',link:(m[1].match(/<link>([\\s\\S]*?)<\\/link>/)||[])[1]||''}));const kw=$('Config').first().json.keywords.split(',').map(s=>s.trim().toLowerCase());const hits=items.filter(i=>kw.some(k=>i.title.toLowerCase().includes(k))).slice(0,10);return [{json:{items:hits.length?hits:items.slice(0,10)}}];"),
  N('Normalize', 'n8n-nodes-base.code', 2, {'jsCode': "return [{json:$input.first().json}];"}),
  ai('Digest', 'Write a 5-bullet weekly digest from these items with a one-line takeaway each. JSON: {"intro":"","bullets":["",""]}', "JSON.stringify($json.items)"),
  mail('Send digest', "$('Config').first().json.emailTo", "'This week in the industry'", "$json.ai.intro + '\\n\\n' + $json.ai.bullets.map(b => '- ' + b).join('\\n') + '\\n\\nSources:\\n' + $json.items.map(i => i.link).join('\\n')")],
 {}, ['Set feedUrl and keywords in Config.'] + S[1:], {'Fetch feed': {'data': '<rss><channel><item><title>AI tool launches</title><link>https://a.com/1</link></item><item><title>Cats</title><link>https://a.com/2</link></item></channel></rss>'}, 'AI: Digest': {'intro': 'Hello', 'bullets': ['a', 'b', 'c', 'd', 'e']}}, ['Send digest'])
