A('28', 'competitor-page-monitor', 'Competitor page change monitor', 'Marketing', 'Checks competitor pricing or landing pages every day, hashes the visible text and alerts you with an AI summary of what changed.',
 cron(6), [cfg(urls='https://competitor.com/pricing'), code('List URLs', "return $('Config').first().json.urls.split(',').map(u=>({json:{url:u.trim()}}));"),
  http('Fetch page', 'GET', '={{ $json.url }}'), code('Hash text', "const out=[];const urls=$('List URLs').all();$input.all().forEach((it,i)=>{const t=String(it.json.data||'').replace(/<script[\\s\\S]*?<\\/script>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\\s+/g,' ').trim();let h=0;for(let k=0;k<t.length;k++){h=(h*31+t.charCodeAt(k))|0;}out.push({json:{url:urls[i].json.url,hash:String(h),text:t.slice(0,4000)}});});return out;"),
  sheet_read('Read last hashes'),
  code('Find changes', "const prev={};for(const it of $input.all()){if(it.json.url)prev[it.json.url]=it.json;}return $('Hash text').all().map(it=>{const p=prev[it.json.url];return {json:{url:it.json.url,hash:it.json.hash,text:it.json.text,changed:!!(p&&p.hash!==it.json.hash),old:p?p.text:''}};});"),
  code('Row: save hash', "return $input.all().map(it=>({json:{date:new Date().toISOString(),url:it.json.url,hash:it.json.hash,text:it.json.text}}));"), sheet_append('Save hashes'),
  iff("$('Find changes').all()[$itemIndex].json.changed", [slack('Alert: page changed', "'Competitor page changed: ' + $('Find changes').all()[$itemIndex].json.url + '\\nWas: ' + $('Find changes').all()[$itemIndex].json.old.slice(0, 160) + '\\nNow: ' + $('Find changes').all()[$itemIndex].json.text.slice(0, 160)")])],
 {}, ['Sheet columns: date, url, hash, text. The first run only records a baseline; later runs alert on change.'] + S[1:], {'Fetch page': {'data': '<html>Price $49 now</html>'}, 'Read last hashes': [{'url': 'https://competitor.com/pricing', 'hash': '1', 'text': 'Price $39'}]}, ['Alert: page changed'])
