A('29', 'hn-reddit-trend-radar', 'Trend radar: Hacker News and Reddit', 'Marketing', 'Scans Hacker News top stories (and any subreddit RSS) for your topics, scores by points and comments, and posts the top five to Slack each morning.',
 cron(8), [cfg(topics='ai agent,automation,saas,n8n'), http('HN top ids', 'GET', 'https://hacker-news.firebaseio.com/v0/topstories.json'),
  code('Top 30 ids', "let ids=[];for(const it of $input.all()){const d=it.json.data!==undefined?it.json.data:it.json;ids=ids.concat(Array.isArray(d)?d:[d]);}return ids.filter(x=>typeof x==='number').slice(0,30).map(id=>({json:{id}}));"),
  http('HN story', 'GET', "={{ 'https://hacker-news.firebaseio.com/v0/item/' + $json.id + '.json' }}"),
  code('Filter and rank', "const kw=$('Config').first().json.topics.split(',').map(s=>s.trim().toLowerCase());const hits=$input.all().map(i=>i.json).filter(s=>s&&s.title&&kw.some(k=>s.title.toLowerCase().includes(k))).sort((a,b)=>(b.score+b.descendants)-(a.score+a.descendants)).slice(0,5);return [{json:{lines:hits.map(s=>'- ' + s.title + ' (' + s.score + ' pts) https://news.ycombinator.com/item?id=' + s.id).join('\\n'),count:hits.length}}];"),
  iff('$json.count > 0', [slack('Post trends', "'Trending on Hacker News today:\\n' + $json.lines")])],
 {}, ['Edit the topics list in Config.'] + S[1:], {'HN top ids': [{'data': 1}, {'data': 2}, {'data': 3}], 'HN story': {'id': 1, 'title': 'Show HN: AI agent for invoices', 'score': 300, 'descendants': 120}}, ['Post trends'])
