A('30', 'seo-content-brief', 'SEO content brief generator', 'Marketing', 'Give it a target keyword; it fetches the top results via SerpAPI-style search, and AI writes an outline, questions to answer, entities to cover and a title and meta description.',
 ('webhook', 'seo-brief'), [cfg(), norm("return [{json:{keyword:b.keyword,audience:b.audience||'small business owners'}}];"),
  http('Search results', 'GET', 'https://serpapi.com/search.json', None, 'SerpAPI (Header Auth or query key)', query="{q:$json.keyword,num:10,engine:'google'}"),
  code('Collect titles', "const r=$input.first().json;const o=(r.organic_results||[]).slice(0,8).map(x=>x.title+' - '+(x.snippet||''));const q=(r.related_questions||[]).map(x=>x.question);return [{json:{...$('Normalize').first().json,serp:o,questions:q}}];"),
  ai('Brief', 'Write an SEO content brief that would out-rank the listed results by being more useful. JSON: {"title":"","meta":"","outline":["H2 ..."],"must_answer":[""],"entities":[""]}', "JSON.stringify({keyword:$json.keyword,audience:$json.audience,serp:$json.serp,questions:$json.questions})"),
  mail('Email brief', "$('Config').first().json.emailTo", "'Brief: ' + $json.keyword", "$json.ai.title + '\\n' + $json.ai.meta + '\\n\\n' + $json.ai.outline.join('\\n') + '\\n\\nAnswer:\\n' + $json.ai.must_answer.join('\\n')")],
 {'keyword': 'invoice automation for freelancers'}, ['SerpAPI key goes in the credential (or swap for any search API).'] + S[1:], {'Search results': {'organic_results': [{'title': 'T1', 'snippet': 's'}], 'related_questions': [{'question': 'What is invoice automation?'}]}, 'AI: Brief': {'title': 'Invoice automation guide', 'meta': 'm', 'outline': ['H2 a', 'H2 b'], 'must_answer': ['Q1'], 'entities': ['Stripe']}}, ['Email brief'])
