A('32', 'mention-sentiment-alert', 'Social and web mention sentiment alert', 'Marketing', 'Webhook from a listening tool or Zapier-style feed; AI scores sentiment and reach, alerting Slack on negative or high-reach mentions.',
 ('webhook', 'mention'), [cfg(), norm("return [{json:{source:b.source||'web',author:b.author||'',text:String(b.text||'').slice(0,1500),followers:Number(b.followers||0),url:b.url||''}}];"),
  ai('Sentiment', 'Score a brand mention. JSON: {"sentiment":"positive|neutral|negative","topic":"","needs_reply":true}', "JSON.stringify($json)"),
  iff("$json.ai.sentiment === 'negative' || $json.followers >= 10000 || $json.ai.needs_reply", [slack('Alert: mention', "'[' + $json.ai.sentiment + '] ' + $json.source + ' by ' + $json.author + ' (' + $json.followers + ' followers): ' + $json.text + ' ' + $json.url")], [row('Row: mention', "return [{json:{date:new Date().toISOString(),source:j.source,sentiment:j.ai.sentiment,url:j.url}}];"), sheet_append('Log mention')])],
 {'source': 'x', 'author': '@maya', 'text': 'Your checkout is broken again!', 'followers': 52000, 'url': 'https://x.com/1'}, S, {'AI: Sentiment': {'sentiment': 'negative', 'topic': 'checkout', 'needs_reply': True}}, ['Alert: mention'], ['Log mention'])
