A('33', 'ad-spend-anomaly', 'Ad spend anomaly alert', 'Marketing', 'Reads daily spend and conversions from a sheet your ad exports feed, computes a rolling baseline and alerts when CPA or spend jumps more than 40 percent.',
 cron(9), [cfg(threshold='40'), sheet_read('Read ad data'),
  code('Compare', "const rows=$input.all().map(i=>i.json).filter(r=>r.date).sort((a,b)=>new Date(a.date)-new Date(b.date));if(rows.length<4)return [{json:{none:true}}];const last=rows[rows.length-1],base=rows.slice(-8,-1);const avg=k=>base.reduce((a,r)=>a+Number(r[k]||0),0)/base.length;const cpa=r=>Number(r.conversions)?Number(r.spend)/Number(r.conversions):Infinity;const baseCpa=base.reduce((a,r)=>a+cpa(r),0)/base.length;const t=Number($('Config').first().json.threshold)/100;const spendUp=Number(last.spend)>avg('spend')*(1+t);const cpaUp=isFinite(cpa(last))?cpa(last)>baseCpa*(1+t):Number(last.spend)>0;return [{json:{none:!(spendUp||cpaUp),date:last.date,spend:Number(last.spend),avgSpend:avg('spend'),cpa:isFinite(cpa(last))?cpa(last):0,baseCpa}}];"),
  iff('!$json.none', [slack('Alert: ad anomaly', "'Ad anomaly ' + $json.date + ': spend $' + $json.spend.toFixed(0) + ' vs avg $' + $json.avgSpend.toFixed(0) + ', CPA $' + $json.cpa.toFixed(2) + ' vs $' + $json.baseCpa.toFixed(2)")])],
 {}, ['Sheet columns: date, spend, conversions (one row per day).'] + S[1:], {'Read ad data': [{'date': '2026-11-10', 'spend': '100', 'conversions': '10'}, {'date': '2026-11-11', 'spend': '100', 'conversions': '10'}, {'date': '2026-11-12', 'spend': '100', 'conversions': '10'}, {'date': '2026-11-13', 'spend': '100', 'conversions': '10'}, {'date': '2026-11-14', 'spend': '100', 'conversions': '10'}, {'date': '2026-11-15', 'spend': '400', 'conversions': '5'}]}, ['Alert: ad anomaly'])
