A('34', 'content-calendar-publisher', 'Content calendar auto-publisher', 'Marketing', 'Every hour posts anything in your content sheet scheduled for now to a webhook (Buffer, Make, or your CMS) and marks it posted.',
 hourly(1), [cfg(publishUrl='https://example.com/publish-webhook'), sheet_read('Read calendar'),
  code('Due posts', "const now=Date.now();const out=[];for(const it of $input.all()){const r=it.json;if(String(r.status).toUpperCase()!=='SCHEDULED')continue;if(new Date(r.publish_at).getTime()<=now)out.push({json:{row:r.row_number||'',channel:r.channel,text:r.text,link:r.link||''}});}return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [http('Publish', 'POST', "={{ $('Config').first().json.publishUrl }}", "{channel:$('Due posts').all()[$itemIndex].json.channel,text:$('Due posts').all()[$itemIndex].json.text,link:$('Due posts').all()[$itemIndex].json.link}"),
   N('Mark posted', 'n8n-nodes-base.googleSheets', 4.5, {'resource': 'sheet', 'operation': 'update', 'documentId': {'__rl': True, 'value': "={{ $('Config').first().json.sheetId }}", 'mode': 'id'}, 'sheetName': {'__rl': True, 'value': 'Sheet1', 'mode': 'name'}, 'columns': {'mappingMode': 'defineBelow', 'value': {'row_number': "={{ $('Due posts').all()[$itemIndex].json.row }}", 'status': 'POSTED'}, 'matchingColumns': ['row_number'], 'schema': []}, 'options': {}}, {'googleSheetsOAuth2Api': {'id': '', 'name': 'Google Sheets account'}}),
   slack('Log: published', "'Published to ' + $('Due posts').all()[$itemIndex].json.channel + ': ' + $('Due posts').all()[$itemIndex].json.text.slice(0, 80)")])],
 {}, ['Sheet columns: publish_at (ISO), channel, text, link, status (SCHEDULED/POSTED).', 'Posted rows are marked POSTED automatically (matched by row_number).'] + S[1:], {'Read calendar': [{'publish_at': '2020-01-01T00:00:00Z', 'channel': 'linkedin', 'text': 'Hello world', 'status': 'SCHEDULED'}, {'publish_at': '2999-01-01T00:00:00Z', 'channel': 'x', 'text': 'Later', 'status': 'SCHEDULED'}]}, ['Publish', 'Mark posted', 'Log: published'])
